/* ================================================================
   app.js — Application cotes-menuiserie
   ----------------------------------------------------------------
   - Gère une liste dynamique de menuiseries (ajout / suppression)
   - Affiche dynamiquement le schéma SVG correspondant à
     la combinaison (pose, type) via schemas.js
   - Pas de section tarification (volontairement retirée)
   - Génère un rapport imprimable avec aperçu à l'écran
   ================================================================ */

(function () {
  'use strict';

  // ---------- Types de vitrages (uniquement à titre informatif) ----
  const VITRAGE_TYPES = [
    'Vitrage fixe',
    'Double vitrage',
    'Triple vitrage',
    'Vitrage dépoli',
    'Vitrage fixe sécurité',
    'Plein',
    'Autre'
  ];

  // ---------- État global -----------------------------------------
  const menuiseries = [];
  let menuiserieCounter = 0;

  // ---------- Initialisation --------------------------------------
  document.addEventListener('DOMContentLoaded', () => {
    const dateInput = document.getElementById('date');
    if (dateInput) dateInput.valueAsDate = new Date();

    const addBtn   = document.getElementById('addMenuiserieBtn');
    const prevBtn  = document.getElementById('previewBtn');
    const genBtn   = document.getElementById('generatePdfBtn');
    const closeBtn = document.getElementById('closePreviewBtn');

    if (addBtn)   addBtn.addEventListener('click', addMenuiserie);
    if (prevBtn)  prevBtn.addEventListener('click', showSchemaPreview);
    if (genBtn)   genBtn.addEventListener('click', generateReport);
    if (closeBtn) closeBtn.addEventListener('click', closePreview);

    // Une menuiserie par défaut pour faciliter la prise en main
    addMenuiserie();
  });

  // ---------- Helpers schémas -------------------------------------
  function buildSchemaImg(pose, type, alt) {
    const path = window.getSchemaPath ? window.getSchemaPath(pose, type) : null;
    if (!path) {
      return '<div class="schema-missing">Schéma indisponible pour pose="' +
        (pose || '') + '", type="' + (type || '') + '".</div>';
    }
    // <img> charge le SVG directement — fonctionne hors-ligne, parfait
    // pour le PDF (html2canvas rasterise la balise).
    return '<img class="schema-svg" src="' + path + '" alt="' +
      (alt || 'Schéma de pose') + '" />';
  }

  // ---------- CRUD menuiseries ------------------------------------
  function addMenuiserie() {
    const pose = (window.POSES && window.POSES[0]) ? window.POSES[0].value : 'applique';
    const type = (window.TYPES_MENUISERIE && window.TYPES_MENUISERIE[0])
      ? window.TYPES_MENUISERIE[0].value : 'fenetre';

    const m = {
      id: ++menuiserieCounter,
      numero: menuiseries.length + 1,
      pose: pose,
      type: type,
      largeur: '',
      hauteur: '',
      coteBati: '',
      vitrage: 'Double vitrage',
      reference: '',
      notes: ''
    };

    menuiseries.push(m);
    renderMenuiserie(m);
  }

  function removeMenuiserie(id) {
    const idx = menuiseries.findIndex(m => m.id === id);
    if (idx === -1) return;
    menuiseries.splice(idx, 1);
    const el = document.getElementById('menuiserie-' + id);
    if (el) el.remove();
    // Re-numérotation
    menuiseries.forEach((m, i) => {
      m.numero = i + 1;
      const numEl = document.querySelector('#menuiserie-' + m.id + ' .numero');
      if (numEl) numEl.textContent = 'Menuiserie ' + m.numero;
    });
    if (menuiseries.length === 0) addMenuiserie();
  }

  function updateMenuiserie(id, field, value) {
    const m = menuiseries.find(r => r.id === id);
    if (!m) return;
    m[field] = value;
    // Si pose ou type changent → rafraîchir le schéma d'aperçu local
    if (field === 'pose' || field === 'type') {
      const localSchema = document.getElementById('localSchema-' + id);
      if (localSchema) {
        localSchema.innerHTML = buildSchemaImg(
          m.pose, m.type,
          'Schéma pose ' + m.pose + ' — ' + m.type
        );
      }
    }
  }

  // ---------- Rendu du formulaire d'une menuiserie ----------------
  function renderMenuiserie(m) {
    const container = document.getElementById('menuiseriesContainer');
    if (!container) return;

    const posesOpts = (window.POSES || []).map(p =>
      '<option value="' + p.value + '"' +
      (p.value === m.pose ? ' selected' : '') + '>' + p.label + '</option>'
    ).join('');

    const typesOpts = (window.TYPES_MENUISERIE || []).map(t =>
      '<option value="' + t.value + '"' +
      (t.value === m.type ? ' selected' : '') + '>' + t.label + '</option>'
    ).join('');

    const vitrageOpts = VITRAGE_TYPES.map(v =>
      '<option value="' + v + '"' +
      (v === m.vitrage ? ' selected' : '') + '>' + v + '</option>'
    ).join('');

    const card = document.createElement('div');
    card.className = 'menuiserie-card';
    card.id = 'menuiserie-' + m.id;

    card.innerHTML =
      '<div class="menuiserie-header">' +
        '<h3 class="numero">Menuiserie ' + m.numero + '</h3>' +
        '<button type="button" class="btn-remove" ' +
          'data-remove="' + m.id + '">Supprimer</button>' +
      '</div>' +

      '<div class="menuiserie-fields">' +
        '<div class="form-group">' +
          '<label>Pose :</label>' +
          '<select data-field="pose" data-id="' + m.id + '">' + posesOpts + '</select>' +
        '</div>' +

        '<div class="form-group">' +
          '<label>Type de menuiserie :</label>' +
          '<select data-field="type" data-id="' + m.id + '">' + typesOpts + '</select>' +
        '</div>' +

        '<div class="form-group">' +
          '<label>Largeur (mm) :</label>' +
          '<input type="number" data-field="largeur" data-id="' + m.id + '" ' +
            'placeholder="Ex: 1500" value="' + (m.largeur || '') + '" />' +
        '</div>' +

        '<div class="form-group">' +
          '<label>Hauteur (mm) :</label>' +
          '<input type="number" data-field="hauteur" data-id="' + m.id + '" ' +
            'placeholder="Ex: 1200" value="' + (m.hauteur || '') + '" />' +
        '</div>' +

        '<div class="form-group">' +
          '<label>Cote Bâti (mm) :</label>' +
          '<input type="number" data-field="coteBati" data-id="' + m.id + '" ' +
            'placeholder="Ex: 1180" value="' + (m.coteBati || '') + '" />' +
        '</div>' +

        '<div class="form-group">' +
          '<label>Type de vitrage :</label>' +
          '<select data-field="vitrage" data-id="' + m.id + '">' + vitrageOpts + '</select>' +
        '</div>' +

        '<div class="form-group">' +
          '<label>Référence panneau :</label>' +
          '<input type="text" data-field="reference" data-id="' + m.id + '" ' +
            'placeholder="Ex: SASHA 1" value="' + (m.reference || '') + '" />' +
        '</div>' +

        '<div class="form-group form-group-wide">' +
          '<label>Notes :</label>' +
          '<input type="text" data-field="notes" data-id="' + m.id + '" ' +
            'placeholder="Infos supplémentaires" value="' + (m.notes || '') + '" />' +
        '</div>' +
      '</div>' +

      '<div class="local-schema" id="localSchema-' + m.id + '">' +
        buildSchemaImg(m.pose, m.type,
          'Pose ' + m.pose + ' — ' + m.type) +
      '</div>';

    // Listeners (délégation)
    card.querySelectorAll('[data-field]').forEach(function (el) {
      const evt = (el.tagName === 'SELECT') ? 'change' : 'input';
      el.addEventListener(evt, function () {
        updateMenuiserie(parseInt(el.dataset.id, 10), el.dataset.field, el.value);
      });
    });
    const removeBtn = card.querySelector('[data-remove]');
    if (removeBtn) {
      removeBtn.addEventListener('click', function () {
        removeMenuiserie(parseInt(removeBtn.dataset.remove, 10));
      });
    }

    container.appendChild(card);
  }

  // ---------- Aperçu (toutes menuiseries) -------------------------
  function showSchemaPreview() {
    const container = document.getElementById('schemaContainer');
    if (!container) return;
    container.innerHTML = '';

    menuiseries.forEach(function (m) {
      const wrap = document.createElement('div');
      wrap.className = 'preview-item';
      wrap.innerHTML =
        '<h3 style="text-align:center;color:#2c3e50;">Menuiserie ' + m.numero + '</h3>' +
        buildSchemaImg(m.pose, m.type, 'Pose ' + m.pose + ' — ' + m.type) +
        '<div class="preview-infos">' +
          '<p><strong>Pose :</strong> ' + labelPose(m.pose) + '</p>' +
          '<p><strong>Type :</strong> ' + labelType(m.type) + '</p>' +
          '<p><strong>Dimensions :</strong> ' +
            (m.largeur || '—') + ' × ' + (m.hauteur || '—') + ' mm</p>' +
          '<p><strong>Cote Bâti :</strong> ' + (m.coteBati || '—') + ' mm</p>' +
          '<p><strong>Vitrage :</strong> ' + m.vitrage + '</p>' +
          (m.reference ? '<p><strong>Référence :</strong> ' + m.reference + '</p>' : '') +
          (m.notes ? '<p><strong>Notes :</strong> ' + m.notes + '</p>' : '') +
        '</div>';
      container.appendChild(wrap);
    });

    const section = document.getElementById('previewSection');
    if (section) {
      section.style.display = 'block';
      section.scrollIntoView({ behavior: 'smooth' });
    }
  }

  function closePreview() {
    const section = document.getElementById('previewSection');
    if (section) section.style.display = 'none';
  }

  // ---------- Libellés humains ------------------------------------
  function labelPose(v) {
    const p = (window.POSES || []).find(function (x) { return x.value === v; });
    return p ? p.label : v;
  }
  function labelType(v) {
    const t = (window.TYPES_MENUISERIE || []).find(function (x) { return x.value === v; });
    return t ? t.label : v;
  }

  // ---------- Génération du rapport -------------------------------
  function generateReport() {
    try {
      const clientName   = (document.getElementById('clientName')   || {}).value || '';
      const reference    = (document.getElementById('reference')    || {}).value || '';
      const date         = (document.getElementById('date')         || {}).value || '';
      const bicoloration = (document.getElementById('bicoloration') || {}).value || '';

      if (menuiseries.length === 0 ||
          !menuiseries.some(function (m) { return m.largeur || m.hauteur; })) {
        alert('Veuillez ajouter au moins une menuiserie avec des dimensions.');
        return;
      }

      const element = buildReportElement({
        clientName: clientName.trim(),
        reference:  reference.trim(),
        date:       date,
        bicoloration: bicoloration.trim()
      });

      // 1) Aperçu à l'écran (clé : l'utilisateur voit ce qu'il télécharge)
      showReportPreview(element);

      // 2) Génération PDF via html2pdf (CDN) — avec fallback window.print()
      const opt = {
        margin: 10,
        filename: 'cotes-menuiserie-' +
          ((reference || 'rapport').replace(/\s+/g, '_')) + '.pdf',
        image: { type: 'jpeg', quality: 0.98 },
        html2canvas: { scale: 2, useCORS: true },
        jsPDF: { orientation: 'portrait', unit: 'mm', format: 'a4' },
        pagebreak: { mode: ['css', 'legacy'] }
      };

      if (typeof html2pdf !== 'function') {
        console.warn('[rapport] html2pdf indisponible, fallback window.print()');
        window.print();
        return;
      }

      html2pdf().set(opt).from(element).save()
        .catch(function (err) {
          console.error('[rapport] échec html2pdf :', err);
          alert("La génération du PDF a échoué. L'aperçu reste affiché — Ctrl+P pour imprimer.");
        });
    } catch (err) {
      console.error('[rapport] erreur generateReport :', err);
      alert("Une erreur est survenue lors de la génération du rapport.");
    }
  }

  function buildReportElement(opts) {
    const element = document.createElement('div');
    element.id = 'pdfSource';
    element.style.padding = '20px';
    element.style.fontFamily = 'Arial, sans-serif';
    element.style.fontSize  = '12px';
    element.style.background = '#ffffff';
    element.style.color = '#000';

    // Entête
    const header = document.createElement('div');
    header.style.textAlign = 'center';
    header.style.marginBottom = '30px';
    header.style.borderBottom = '2px solid #333';
    header.style.paddingBottom = '20px';
    header.innerHTML =
      '<h1 style="margin:0;color:#2c3e50;">RAPPORT DE COTES MENUISERIE</h1>' +
      '<p style="margin:10px 0 0 0;color:#7f8c8d;">' +
        new Date().toLocaleDateString('fr-FR') + '</p>';
    element.appendChild(header);

    // Informations client / chantier
    const infos = document.createElement('div');
    infos.style.marginBottom = '30px';
    infos.innerHTML =
      '<table style="width:100%;border-collapse:collapse;">' +
        '<tr>' +
          '<td style="padding:8px;width:50%;"><strong>Client :</strong> ' +
            (opts.clientName || '—') + '</td>' +
          '<td style="padding:8px;width:50%;"><strong>Référence :</strong> ' +
            (opts.reference || '—') + '</td>' +
        '</tr>' +
        '<tr>' +
          '<td style="padding:8px;"><strong>Date :</strong> ' +
            (opts.date || '—') + '</td>' +
          '<td style="padding:8px;"><strong>Bicoloration PVC :</strong> ' +
            (opts.bicoloration || '—') + '</td>' +
        '</tr>' +
      '</table>';
    element.appendChild(infos);

    // Une page par menuiserie
    menuiseries.forEach(function (m, index) {
      const page = document.createElement('div');
      page.style.pageBreakAfter = 'always';
      page.style.marginTop = (index > 0 ? '40px' : '0');

      const title = document.createElement('h2');
      title.style.color = '#2c3e50';
      title.style.marginBottom = '20px';
      title.textContent = 'Menuiserie ' + m.numero;
      page.appendChild(title);

      // Schéma via <img src=…> (rasterisable par html2canvas)
      const imgWrap = document.createElement('div');
      imgWrap.style.textAlign = 'center';
      imgWrap.style.marginBottom = '20px';
      imgWrap.innerHTML = buildSchemaImg(
        m.pose, m.type,
        'Pose ' + m.pose + ' — ' + m.type
      );
      page.appendChild(imgWrap);

      // Tableau d'informations
      const table = document.createElement('table');
      table.style.width = '100%';
      table.style.borderCollapse = 'collapse';
      table.style.marginBottom = '20px';
      table.innerHTML =
        '<tr style="background:#ecf0f1;">' +
          '<td style="padding:8px;font-weight:bold;width:35%;">Pose</td>' +
          '<td style="padding:8px;">' + labelPose(m.pose) + '</td>' +
        '</tr>' +
        '<tr>' +
          '<td style="padding:8px;font-weight:bold;">Type</td>' +
          '<td style="padding:8px;">' + labelType(m.type) + '</td>' +
        '</tr>' +
        '<tr style="background:#ecf0f1;">' +
          '<td style="padding:8px;font-weight:bold;">Dimensions (mm)</td>' +
          '<td style="padding:8px;">L: ' + (m.largeur || '—') +
            ' × H: ' + (m.hauteur || '—') + '</td>' +
        '</tr>' +
        '<tr>' +
          '<td style="padding:8px;font-weight:bold;">Cote Bâti</td>' +
          '<td style="padding:8px;">' + (m.coteBati || '—') + ' mm</td>' +
        '</tr>' +
        '<tr style="background:#ecf0f1;">' +
          '<td style="padding:8px;font-weight:bold;">Vitrage</td>' +
          '<td style="padding:8px;">' + m.vitrage + '</td>' +
        '</tr>' +
        (m.reference ?
          '<tr>' +
            '<td style="padding:8px;font-weight:bold;">Référence</td>' +
            '<td style="padding:8px;">' + m.reference + '</td>' +
          '</tr>' : '') +
        (m.notes ?
          '<tr style="background:#ecf0f1;">' +
            '<td style="padding:8px;font-weight:bold;">Notes</td>' +
            '<td style="padding:8px;">' + m.notes + '</td>' +
          '</tr>' : '');
      page.appendChild(table);

      element.appendChild(page);
    });

    return element;
  }

  function showReportPreview(element) {
    const previewSection  = document.getElementById('previewSection');
    const schemaContainer = document.getElementById('schemaContainer');
    if (!previewSection || !schemaContainer) return;
    schemaContainer.innerHTML = '';
    schemaContainer.appendChild(element);
    previewSection.style.display = 'block';
    previewSection.scrollIntoView({ behavior: 'smooth' });
  }
})();

/* ================================================================
   schemas.js — Mapping pose + type de menuiserie → chemin SVG
   ================================================================
   - Expose window.SCHEMAS : map { 'pose-type' -> chemin relatif }
   - Expose window.getSchemaPath(pose, type) : résolution d'URL
   - Expose window.POSES et window.TYPES_MENUISERIE pour peupler
     les <select> de l'UI.
   ================================================================ */

(function () {
  'use strict';

  // Poses disponibles
  const POSES = [
    { value: 'applique',   label: 'Pose en applique' },
    { value: 'tunnel',     label: 'Pose en tunnel' },
    { value: 'feuillure',  label: 'Pose en feuillure' },
    { value: 'renovation', label: 'Pose en rénovation' }
  ];

  // Types de menuiserie
  const TYPES_MENUISERIE = [
    { value: 'fenetre', label: 'Fenêtre' },
    { value: 'porte',   label: 'Porte-fenêtre' },
    { value: 'baie',    label: 'Baie coulissante / vitrée' }
  ];

  // Convention : triangles orange = limites de l'ouverture brute,
  // mur = motif brique. Chaque combinaison (pose, type) pointe vers
  // le SVG dédié rangé dans assets/schemas/.
  const SCHEMAS = {
    'applique-fenetre':    'assets/schemas/pose-applique-fenetre.svg',
    'applique-porte':      'assets/schemas/pose-applique-porte.svg',
    'applique-baie':       'assets/schemas/pose-applique-baie.svg',
    'tunnel-fenetre':      'assets/schemas/pose-tunnel-fenetre.svg',
    'tunnel-porte':        'assets/schemas/pose-tunnel-porte.svg',
    'tunnel-baie':         'assets/schemas/pose-tunnel-baie.svg',
    'feuillure-fenetre':   'assets/schemas/pose-feuillure-fenetre.svg',
    'feuillure-porte':     'assets/schemas/pose-feuillure-porte.svg',
    'renovation-fenetre':  'assets/schemas/pose-renovation-fenetre.svg',
    'renovation-porte':    'assets/schemas/pose-renovation-porte.svg'
  };

  /**
   * Résout le chemin du schéma SVG pour une combinaison (pose, type).
   * @param {string} pose — applique | tunnel | feuillure | renovation
   * @param {string} type — fenetre | porte | baie
   * @returns {string|null} chemin relatif vers le SVG, ou null
   */
  function getSchemaPath(pose, type) {
    const key = (pose || '') + '-' + (type || '');
    if (SCHEMAS[key]) return SCHEMAS[key];
    console.warn('[schemas.js] Pas de schéma pour pose="' + pose + '", type="' + type + '"');
    return null;
  }

  /**
   * Liste tous les schémas disponibles (utile pour debug / itération).
   */
  function listSchemas() {
    return Object.keys(SCHEMAS);
  }

  window.POSES            = POSES;
  window.TYPES_MENUISERIE = TYPES_MENUISERIE;
  window.SCHEMAS          = SCHEMAS;
  window.getSchemaPath    = getSchemaPath;
  window.listSchemas      = listSchemas;
})();
